 TaskMessageReturnState state;TaskMessageReturnStart start;start.fact_id="task_message_return_started:8";start.task_id="task:2";start.offer_id="round_trip";start.policy_id="return";start.handoff_fact_id="task_message_handoff:5";start.action_id="action:7";start.carrier_actor_id="carrier";start.recipient_actor_id="recipient";start.sender_actor_id="sender";start.reply_item_id="reply";start.carrier_inventory_id="bag";start.session_id="interaction:6";start.dialogue_id="reply.talk";start.node_id="entrust";start.context.place_id="door";start.context.provider_actor_id="recipient";start.context.role_id="recipient.role";start.started_tick=4;start.actual_result=TaskMessageReturnResult{"result:9","carrier","task_message_return_collect",3,5,4,4};const auto start_id=start.fact_id;state.starts.insert(start_id,start);
 TaskMessageReturnCollection collected;collected.fact_id="task_message_return_collected:11";collected.start_fact_id=start_id;collected.task_id=start.task_id;collected.action_id=start.action_id;collected.reply_lot_id="lot:10";collected.tick=5;collected.success=true;collected.actual_result=TaskMessageReturnResult{"result:12","carrier","advance",4,6,4,5};state.collections.insert(collected.fact_id,collected);
