 TaskMessageReturnReportStart report;report.fact_id="task_message_return_report_started:19";report.task_id=start.task_id;report.collection_fact_id=collected.fact_id;report.action_id="action:18";report.original_lot_id=collected.reply_lot_id;report.from_inventory_id="bag";report.to_inventory_id="sender.bag";report.carrier_actor_id="carrier";report.sender_actor_id="sender";report.session_id="interaction:17";report.dialogue_id="sender.talk";report.node_id="report";report.context.place_id="door";report.context.provider_actor_id="sender";report.context.role_id="sender.role";report.started_tick=8;report.actual_result=TaskMessageReturnResult{"result:20","carrier","report_offer",7,9,8,8};state.report_starts.insert(report.fact_id,report);
