 auto raw=encode_task_message_returns(state);auto decoded=decode_task_message_returns(raw);check(decoded.ok&&compare_boundary(raw,encode_task_message_returns(decoded.value)).exact(),"all five table payloads and actual results round trip exactly");
 auto start_fact=encode_task_message_return_fact(state,start_id);check(start_fact.ok&&start_fact.value.find("actual_result"),"fact export includes permanent actual result");check(!encode_task_message_return_fact(state,"absent").ok,"unknown source has no fabricated fact payload");
