 auto absent=state;absent.starts.find(start_id)->actual_result.reset();auto pending=decode_task_message_returns(encode_task_message_returns(absent));check(pending.ok&&!pending.value.starts.find(start_id)->actual_result,"codec preserves unbound candidate rather than inventing actual result; full validator must reject persisted unbound");
